    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(i):
            if time[j] <= time[i] and cost[j] + dp[j] < dp[i]:
                dp[i] = cost[j] + dp[j]
    return dp[n]

def minSumOfKAvoid(n, k):
    def isKAvoiding(arr):
        for i in range(n):
            for j in range(i+1, n):
                if arr[i] + arr[j] == k:
                    return False
        return True

    def kAvoidingArray(n, k):
        for i in range(n):
            for j in range(i+1, n):
                if arr[i] + arr[j] == k:
                    arr.remove(arr[i])
                    arr.remove(arr[j])
                    return True
        return False

    arr = [i for i in range(1, n+1)]
    while True:
        if not isKAvoiding(arr):
            return sum(arr)
        arr = kAvoidingArray(n, k)

def maxAchievableNumber(num, t):
    # Initialize the maximum achievable number
    max_achievable = num

    # Iterate over the range of possible achievable numbers
    for i in range(num, num + t + 1):
        # Check if the current number is achievable
        if i % 2 == 0:
            max_achievable = max(max_achievable, i // 2)
        else:
            max_achievable = max(max_achievable, i // 2 + 1)

    return max_achievable

def minPalindrome(s):
    n = len(s)
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = 1
        for j in range(i):
            if s[i] == s[j]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return s[dp[n-1][n-1]:n-1:-1]

def minCost(s):
