    for i in range(n):
        dp[i][i] = 0
    for l in range(2, n+1):
        for i in range(n-l+1):
            j = i + l - 1
            if l == 2:
                dp[i][j] = min(dp[i][j], dp[i+1][j-1])
            else:
                dp[i][j] = min(dp[i][j], dp[i+1][j-1] + (s[i] == s[j]))
    return dp[0][n-1]

