def minimizeString(s):
    s = list(s)
    min_len = len(s)
    for i in range(len(s)):
        if i == 0:
            if s[i] != s[i+1]:
                s[i] = s[i+1]
                min_len -= 1
        elif i == len(s)-1:
            if s[i] != s[i-1]:
                s[i] = s[i-1]
                min_len -= 1
        else:
            if s[i] != s[i-1] and s[i] != s[i+1]:
                s[i] = s[i-1]
                min_len -= 1
    return min_len

