def countServers(n, logs, x, queries):
    servers = [0] * n
    for log in logs:
        servers[log[0]] += 1
    result = [0] * len(queries)
    for i in range(len(queries)):
        start = queries[i] - x
        end = queries[i]
        result[i] = sum(1 for j in range(start, end) if servers[j] == 0)
    return result

