def prime_pairs(n):
    prime_list = [i for i in range(2, n+1) if all(i % j != 0 for j in range(2, int(i**0.5) + 1))]
    prime_pairs = []
    for i in range(len(prime_list)):
        for j in range(i+1, len(prime_list)):
            if prime_list[i] + prime_list[j] == n:
                prime_pairs.append([prime_list[i], prime_list[j]])
    prime_pairs.sort(key=lambda x: x[0])
    return prime_pairs

