def minDominantIndex(nums):
    m = max(nums)
    if len(set(nums)) == 1:
        return -1
    else:
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1
        dominant = max(freq.values())
        if dominant * 2 > len(nums):
            return nums.index(m)
        else:
            return -1

