def maxGroups(usageLimits):
    n = len(usageLimits)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3]
        if i >= 3:
            dp[i] = min(dp[i], dp[i - 1] + usageLimits[i - 1])
    return dp[n]

def countSteppingNumbers(low, high):
    def isSteppingNumber(n):
        return (n - int(str(n)[:-1]) == 1) or (n - int(str(n)[:-1]) == -1)

    count = 0
    for i in range(int(low), int(high) + 1):
        if isSteppingNumber(i):
            count += 1

    return count % (10**9 + 7)

def findPairs(coordinates, k):
