    n = len(moves)
    max_distance = 0
    for i in range(n):
        if moves[i] == 'L' or moves[i] == '_':
            max_distance = max(max_distance, i)
        elif moves[i] == 'R' or moves[i] == '_':
            max_distance = max(max_distance, n - i - 1)
