def numWays(s, t, k):
    n = len(s)
    mod = 10**9 + 7
    dp = [[0]*(k+1) for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(1, k+1):
            if s[i-1] == t[i-1]:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % mod
            else:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % mod
    return dp[n][k]

def minOperations(nums, target):
