    i = 0
    while i < n and nums[i] <= target:
        target -= nums[i]
        i += 1
    if i == n:
        return -1
    else:
        return i

def productMatrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            p[i][j] = grid[i][j]
            for k in range(m):
                if k != j:
                    p[i][j] = (p[i][j] * grid[i][k]) % 12345
    return p

