def minOperations(nums):
    n = len(nums)
    if n == 0:
        return 0
    if n == 1:
        return -1
    if n == 2:
        return 0 if nums[0] == nums[1] else -1

    count = [0] * 100001
    for num in nums:
        count[num] += 1

    res = float('inf')
    for i in range(1, n):
        if count[i] == 0:
            continue
        if count[i] == 1:
            res = min(res, i)
        else:
            res = min(res, i + count[i] - 1)

