def maxSumBeautifulTowers(maxHeights):
    def is_beautiful(heights):
        for i in range(1, len(heights)):
            if heights[i] < heights[i-1]:
                return False
        return True

    def find_beautiful_configuration(heights):
        for i in range(len(heights)):
            if heights[i] > maxHeights[i]:
                return False
        return True

    def find_max_sum_beautiful_configuration(heights):
        for i in range(len(heights)):
            if heights[i] > maxHeights[i]:
                return maxHeights[i]
        return max(heights)

    max_sum = 0
    for i in range(len(maxHeights)):
        if is_beautiful(maxHeights[i]):
            max_sum = max(max_sum, find_max_sum_beautiful_configuration(maxHeights[i]))
    return max_sum

def smallestBeautifulSubstring(s, k):
    # Initialize the result string
    result = ""

    # Iterate over all possible substrings of s
    for i in range(len(s)):
        for j in range(i, len(s)):
            # Check if the substring is beautiful
            if sum(1 for c in s[i:j+1] if c == '1') == k:
                # If it is, update the result string
                result = s[i:j+1]

    # Return the lexicographically smallest beautiful substring
