def max_weight(n, edges):
    # Create a graph with n vertices
    graph = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            graph[i][j] = edges[i][j]
            graph[j][i] = edges[i][j]

    # Use dynamic programming to find the maximum weight path
    dp = [[0]*n for _ in range(n)]
    for i in range(n):
        dp[i][i] = edges[i][i]

    for k in range(n):
        for i in range(n):
            for j in range(i+1, n):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j])

    return dp[0][n-1]

