def is_valid_grid(grid):
    # Check if each row contains each number from 1 to 9 exactly once
    for row in grid:
        if len(set(row)) != 9:
            return False

    # Check if each column contains each number from 1 to 9 exactly once
    for col in zip(*grid):
        if len(set(col)) != 9:
            return False

    # Check if each 3x3 grid contains each number from 1 to 9 exactly once
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            subgrid = [grid[i+k][j+l] for k in range(3) for l in range(3)]
            if len(set(subgrid)) != 9:
                return False

    return True

