import math

def solve(H, W, S):
    # Create a graph where each green cell is a vertex
    graph = {}
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                graph[(i, j)] = []
            else:
                graph[(i, j)] = []

    # Add edges between adjacent green cells
    for i in range(H):
        for j in range(W):
            if i > 0 and S[i][j] == '#' and S[i-1][j] == '#':
                graph[(i, j)].append((i-1, j))
            if j > 0 and S[i][j] == '#' and S[i][j-1] == '#':
                graph[(i, j)].append((i, j-1))

    # Perform a breadth-first search (BFS) to find the number of connected components
    def bfs(start):
        queue = [start]
        visited = set()
        while queue:
            node = queue.pop(0)
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    queue.append(neighbor)
        return len(visited)

    # Find the expected number of green connected components
    expected = 0
    for i in range(H):
        for j in range(W):
            if S[i][j] == '#':
                expected += bfs((i, j))
    return expected

