                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)
            elif grid[i][j] == '#':
                energy[i*W + j] = 0
            else:
                energy[i*W + j] = int(grid[i][j])

    queue = [(start, 0)]
    visited = set()
    while queue:
        (i, j), energy = queue.pop(0)
        if (i, j) == goal:
            return True
        if (i, j) in visited:
            continue
        visited.add((i, j))
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = i + dx, j + dy
            if 0 <= nx < H and 0 <= ny < W and energy[nx*W + ny] > energy[i*W + j] + 1:
