def solve(N):
    # Initialize the game board
    board = [0] * N
    for i in range(N):
        board[i] = (i + 1, i + 1)

    # Function to check if a player can win
    def can_win(board, player):
        # Check if the player can win in the next move
        for i in range(N):
            if board[i][0] == board[i][1]:
                return True
            if board[i][0] == player:
                return True
            if board[i][1] == player:
                return True
        return False

    # Function to determine the winner
    def determine_winner(board, player):
        # Check if the player can win in the next move
        if can_win(board, player):
            return player
        # Check if the opponent can win in the next move
        for i in range(N):
            if board[i][0] == board[i][1]:
                return player
        return "Takahashi" if can_win(board, 1 - player) else "Aoki"

    # Determine the winner
    return determine_winner(board, 1)

