    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for x in range(1, j + 1):
                dp[i][j] += dp[i - 1][j - x]
                dp[i][j] %= mod
    return sum(dp[n][j] for j in range(1, k + 1))

def min_levels_to_win(possible):
    n = len(possible)
    dp = [0] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        if possible[i - 1] == 0:
            dp[i] = dp[i - 1]
        else:
            dp[i] = max(dp[i - 1], dp[i - 2] + 1)
    return n - dp[n]

def sumOfSubsequenceWeights(nums, k):
    MOD = 10**9 + 7
    dp = [0] * (k + 1)
    dp[0] = 0
    for num in nums:
        for i in range(k, num - 1, -1):
            dp[i] = (dp[i] + dp[i - num]) % MOD
    return dp[k]

def scoreOfS(s):
    score = 0
    for i in range(len(s)-1):
        score += abs(ord(s[i]) - ord(s[i+1]))
    return score

def maxSubarraySum(nums):
    max_sum = 0
    for i in range(len(nums)):
        max_sum = max(max_sum, nums[i])
    return max_sum

def countSpecialLetters(word):
    count = 0
    for i in range(len(word)):
        if word[i].isupper() and word[i] in word:
            count += 1
    return count

def findMinX(nums1, nums2):
    # Find the frequency of each element in nums1
    freq1 = {}
    for num in nums1:
        freq1[num] = freq1.get(num, 0) + 1

    # Find the frequency of each element in nums2
    freq2 = {}
    for num in nums2:
        freq2[num] = freq2.get(num, 0) + 1

    # Find the difference between the frequencies of each element
    diff = {}
    for num in freq1:
        diff[num] = freq2.get(num, 0) - freq1.get(num, 0)

    # Find the minimum difference
    min_diff = float('inf')
    for num in freq1:
        if freq2.get(num, 0) - freq1.get(num, 0) < min_diff:
            min_diff = freq2.get(num, 0) - freq1.get(num, 0)

    # Find the integer x that makes the difference equal to min_diff
    x = min_diff // 2
    return x

def minArray(n, x):
    nums = [0] * n
    for i in range(n - 1):
        nums[i + 1] = nums[i] * 2 + 1
    nums[n - 1] = x
    return nums[n - 1]

def is_valid_word(word):
    # Check if word has at least 3 characters
    if len(word) < 3:
        return False

    # Check if word contains only digits and English letters
    if not word.isdigit() and not word.isalpha():
        return False

    # Check if word contains at least one vowel
    vowels = 'aeiouAEIOU'
    if word.lower() not in vowels:
        return False

    # Check if word contains at least one consonant
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    if word.lower() not in consonants:
        return False

    return True

def minOperations(word, k):
    n = len(word)
    k = k
    res = 0
    for i in range(n):
        if i % k == 0:
            res += 1
            if i + k - 1 < n:
                res += word[i + k - 1] == word[i]
    return res

def minLength(s):
    # Create a dictionary to store the frequency of each character
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the minimum length of the string t
    min_length = len(s)
    for i in range(len(s)):
        # Check if the substring starting from i and ending at i+len(s)-1 is an anagram
        if all(freq[char] >= freq[char2] for char, char2 in zip(s[i:i+len(s)], s[i+len(s)-1:i-1:-1])):
            min_length = min(min_length, len(s) - i)

    return min_length

def minCost(nums, cost1, cost2):
    n = len(nums)
    dp = [[0]*(cost2+1) for _ in range(n+1)]
    for i in range(n+1):
        dp[i][0] = 0
    for i in range(1, n+1):
        for j in range(1, min(i, cost2)+1):
            dp[i][j] = dp[i-1][j] + cost1
            if j >= nums[i-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-nums[i-1]] + cost2)
    return dp[n][cost2] % (10**9 + 7)

def can_make_square(grid):
    for i in range(3):
        for j in range(3):
            if grid[i][j] == 'B':
                if (i == 0 or i == 2) and (j == 0 or j == 2):
                    return True
                if (i == 1 or i == 3) and (j == 1 or j == 3):
                    return True
    return False

def countRightTriangles(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(i+1, len(grid[0])):
            for k in range(j+1, len(grid[0])):
                if grid[i][j] == 1 and grid[j][k] == 1 and grid[k][i] == 1:
                    count += 1
    return count

def stableArrays(zero, one, limit):
    mod = 10**9 + 7
    dp = [0] * (one + 1)
    dp[0] = 1
    for i in range(zero):
        dp[i + 1] = (dp[i] * (one - i) * (i + 1)) % mod
    for i in range(one):
        dp[i + 1] = (dp[i] * (zero - i) * (i + 1)) % mod
    return sum(dp) % mod

def getPermutationDifference(s, t):
    # Create a dictionary to store the frequency of each character in s
    freq_s = {}
    for char in s:
        if char in freq_s:
            freq_s[char] += 1
        else:
            freq_s[char] = 1

    # Create a dictionary to store the frequency of each character in t
    freq_t = {}
    for char in t:
        if char in freq_t:
            freq_t[char] += 1
        else:
            freq_t[char] = 1

    # Calculate the permutation difference
    permutation_difference = 0
    for char in s:
        if char in freq_t:
            permutation_difference += abs(freq_s[char] - freq_t[char])
        else:
            permutation_difference += abs(freq_s[char])

    return permutation_difference

def is_special_array(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def totalWays(k):
    if k == 0:
        return 1
    elif k == 1:
        return 2
    else:
        return totalWays(k - 1) + totalWays(k - 2) + totalWays(k - 4)

def countGoodPairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % (nums2[j] * k) == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        if i == 0:
            comp += word[i]
        else:
            if word[i] == word[i-1]:
                comp += str(len(word[:i])) + word[i]
            else:
                comp += word[i]
    return comp

def powerful_array(queries):
    big_nums = [1]
    for i in range(1, 1000000):
        big_nums.append(big_nums[-1] * 2)
    result = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product *= big_nums[i]
        result.append(product % mod_i)
    return result

def xor_twice(nums):
    xor_result = 0
    for num in nums:
        if nums.count(num) == 2:
            xor_result ^= num
    return xor_result

def query_indices(nums, queries, x):
    result = []
    for i, num in enumerate(nums):
        if num == x:
            result.append(i)
        elif num > x:
            break
    return result
